window.VO = [{"id":"n01","text":"You're his only alibi.","at":0.24,"t0":0.12,"t1":1.39},{"id":"f00","text":"Tell them I was with you!","at":3.18,"t0":1.59,"t1":3.08},{"id":"n02","text":"Your best friend's locked up for robbing a watch shop.","at":6.66,"t0":3.33,"t1":6.14},{"id":"o01","text":"Last Tuesday, seven forty. Where were you?","at":12.78,"t0":6.39,"t1":9.31},{"id":"n03","text":"The police have one blurry photo. He has you. What did you eat? Check your photos. Nobody photographs a Tuesday.","at":19.22,"t0":9.61,"t1":16.39},{"id":"f01","text":"The stall. It was raining, you had ginger chai, you paid cash, twenty rupees. Remember?","at":34.48,"t0":17.24,"t1":22.76},{"id":"o02","text":"The chaiwala remembers nothing. So what did you drink?","at":46.22,"t0":23.11,"t1":26.6},{"id":"o03","text":"How much did you pay?","at":55.9,"t0":27.95,"t1":29.62},{"id":"o04","text":"That's what he told us.","at":61.64,"t0":30.82,"t1":32.45},{"id":"n04","text":"One more. What did he drink?","at":65.6,"t0":32.8,"t1":34.395},{"id":"n05","text":"He never said. You made that up.","at":71.39,"t0":35.695,"t1":37.525},{"id":"n06","text":"Not one word about his evening, because he wasn't with you.","at":75.75,"t0":37.875,"t1":40.92},{"id":"n07","text":"He was here.","at":82.64,"t0":41.32,"t1":42.145},{"id":"o05","text":"The alibi holds. He can go.","at":85.49,"t0":42.745,"t1":45.325},{"id":"n08","text":"Nothing happened, so you had no Tuesday. Now you've got the one he wrote.","at":91.85,"t0":45.925,"t1":49.775},{"id":"n09","text":"He didn't need you to remember. He needed you not to.","at":100.35,"t0":50.175,"t1":52.925},{"id":"f02","text":"Thanks, yaar. Next time, I'll pay.","at":107.25,"t0":53.625,"t1":55.805},{"id":"n10","text":"Lie researchers call that an unanticipated question.","at":112.71,"t0":56.355,"t1":59.305},{"id":"n11","text":"So ask your best friend one. Where were they last Tuesday at seven forty?","at":119.21,"t0":59.605,"t1":63.6},{"id":"n12","text":"But first: what's on his wrist?","at":130.8,"t0":65.4,"t1":67.12}];
